const claims: Claim[] = [
  // ── Boyhood and apprenticeship ─────────────────────────────────────────
  { id: 'c-born', text: 'Henry Ford was born on 30 July 1863 on a farm in Greenfield Township, near Dearborn, Michigan.', when: '1863-07-30', where: 'Greenfield Township, Michigan', confidence: 'established', sourceIds: ['s-mylife', 's-wiki-ford'] },
  { id: 'c-farm', text: 'Ford wrote later that he disliked farm work and that the labor of farm life pushed him toward machinery and better transportation; he said his toys as a boy were tools.', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-engine-watch', text: 'By his own account he saw a steam road engine at about age twelve, the first vehicle he had seen that was not horse-drawn, and was given a watch the same year; by about fifteen he could do almost any watch repair.', when: '1875-1878', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-ford'] },
  { id: 'c-mother', text: 'His mother died in 1876, an event that devastated him.', when: '1876', confidence: 'probable', sourceIds: ['s-wiki-ford'] },
  { id: 'c-left-1879', text: 'In 1879, aged sixteen, he left the farm for Detroit and worked as an apprentice machinist.', when: '1879', where: 'Detroit, Michigan', confidence: 'established', sourceIds: ['s-wiki-ford', 's-mylife'] },
  { id: 'c-edison-co', text: 'He went to work for the Edison Illuminating Company of Detroit as an engineer and machinist, rising to chief engineer by 1893, while building gasoline engines in a shed behind his rented house.', when: '1891-1893', where: 'Detroit, Michigan', confidence: 'established', sourceIds: ['s-mylife', 's-wiki-ford'] },

  // ── First cars and the Edison friendship ───────────────────────────────
  { id: 'c-quadricycle', text: 'Ford completed his first gasoline-powered vehicle, the Quadricycle, in 1896 and test-drove it on 4 June.', when: '1896-06-04', where: 'Detroit, Michigan', confidence: 'established', sourceIds: ['s-wiki-ford', 's-thf-edison'] },
  { id: 'c-edison-meet', text: 'Ford met Thomas Edison at a convention of electric-company men and received encouragement for his gasoline carriage; Edison became a lifelong friend.', confidence: 'contested', sourceIds: ['s-mylife', 's-thf-edison'], note: 'The Henry Ford places the meeting at the 1896 Association of Edison Illuminating Companies convention in Brooklyn. In My Life and Work (1922) Ford himself recalled a convention at Atlantic City and wrote that it was "probably about 1887 or thereabouts." The two dates cannot both be right, and the 1887 memory is generally treated as a lapse.' },
  { id: 'c-vagabonds', text: 'From 1916 to 1924 Ford, Edison, the tire maker Harvey Firestone and the naturalist John Burroughs took annual camping trips, calling themselves "the Vagabonds"; President Warren Harding visited the 1921 trip.', when: '1916-1924', confidence: 'established', sourceIds: ['s-thf-edison'] },
  { id: 'c-jubilee', text: 'In 1929 Ford hosted Light\'s Golden Jubilee in Dearborn, marking fifty years of the incandescent lamp and dedicating the Edison Institute; Edison died in 1931.', when: '1929-1931', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-thf-edison'] },
  { id: 'c-999', text: 'The racing car "999," driven by Barney Oldfield, was built in 1902; Ford later wrote that it advertised the fact that he could build a fast motor car.', when: '1902', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-ford'] },
  { id: 'c-early-cos', text: 'Ford\'s first car companies did not last: the Detroit Automobile Company (founded 1899) was dissolved in January 1901, and the Henry Ford Company, formed in November 1901, was short-lived.', when: '1899-1902', confidence: 'probable', sourceIds: ['s-wiki-ford'] },
  { id: 'c-fmc', text: 'Ford Motor Company was incorporated on 16 June 1903 with $28,000 in capital; the brothers John and Horace Dodge were among its early investors.', when: '1903-06-16', where: 'Detroit, Michigan', confidence: 'established', sourceIds: ['s-wiki-ford'] },

  // ── The Model T and the moving line ────────────────────────────────────
  { id: 'c-modelt', text: 'Ford introduced the Model T on 1 October 1908; the touring car was priced at about $825.', when: '1908-10-01', confidence: 'established', sourceIds: ['s-wiki-modelt', 's-wiki-ford'] },
  { id: 'c-multitude', text: 'Ford recalled announcing, over the objections of his salesmen, that he would build a single model, a car "for the great multitude," so low in price that a man earning a good salary could own one.', when: '1909', confidence: 'probable', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-price', text: 'Model T prices fell from the high hundreds of dollars to about $260 by the mid-1920s as volume rose.', when: '1908-1925', confidence: 'probable', sourceIds: ['s-wiki-modelt', 's-thf-k12'], note: 'Sources differ on the starting price ($825 or $850) and the lowest price ($260 or $265 depending on body style and year).' },
  { id: 'c-15m', text: 'About 15 million Model Ts were built; the fifteen-millionth left the line on 26 May 1927, and the Model A followed late that year.', when: '1927', confidence: 'established', sourceIds: ['s-wiki-modelt', 's-thf-k12'] },
  { id: 'c-modelt-drivetrain', text: 'The Model T had a two-speed planetary transmission worked by three foot pedals: the left pedal engaged the transmission (low and high gear), the centre pedal reverse and the right pedal the transmission brake. A single universal joint connected it to a torque tube that drove the rear axle.', when: '1908-1927', confidence: 'established', sourceIds: ['s-wiki-modelt'] },
  { id: 'c-modelt-magneto', text: 'The Model T engine had a low-voltage magneto built into its flywheel.', when: '1908-1927', confidence: 'established', sourceIds: ['s-wiki-modelt'] },
  { id: 'c-modelt-chassis', text: 'The Model T had a 100-inch (2,540 mm) wheelbase, a transversely mounted semi-elliptical spring at each of the front and rear axles, wooden artillery wheels (steel wheels were offered only in 1926 and 1927), a fuel tank under the front seat and a throttle lever on the steering wheel.', when: '1908-1927', confidence: 'established', sourceIds: ['s-wiki-modelt'] },
  { id: 'c-highland', text: 'Ford moved production to a large new plant at Highland Park, outside Detroit, which opened in 1910.', when: '1910', where: 'Highland Park, Michigan', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-modelt'] },
  { id: 'c-line-stages', text: 'The moving assembly line came in stages in 1913: flywheel magnetos were moved onto a line around 1 April, and by August the line was extended to complete chassis.', when: '1913', where: 'Highland Park, Michigan', confidence: 'established', sourceIds: ['s-thf-methods', 's-thf-k12'] },
  { id: 'c-93min', text: 'Assembly time for a Model T chassis fell from roughly 12.5 hours to about 93 minutes by early 1914; Ford\'s own book gives the chassis labor time as one hour thirty-three minutes.', when: '1913-1914', confidence: 'established', sourceIds: ['s-thf-methods', 's-mylife'] },
  { id: 'c-line-credit', text: 'The moving line was developed by Ford managers and engineers working together, among them Clarence Avery, Peter Martin, Charles Sorensen and C. Harold Wills.', when: '1913', confidence: 'contested', sourceIds: ['s-wiki-ford', 's-hounshell'], note: 'Individual credit is disputed; Sorensen later claimed a leading role, and Ford\'s own writing presents the line as a company achievement. Hounshell treats mass production as a long technological development in which Ford\'s firm was the decisive actor, not as one man\'s invention.' },

  // ── The Five Dollar Day and the Sociological Department ────────────────
  { id: 'c-5day', text: 'On 5 January 1914 Ford Motor Company announced a minimum of five dollars for an eight-hour day, in place of a nine-hour day paid about $2.30 to $2.34; it was structured as a profit-sharing plan rather than a plain wage rise.', when: '1914-01-05', where: 'Highland Park, Michigan', confidence: 'established', sourceIds: ['s-thf-5day', 's-mylife', 's-wiki-ford'] },
  { id: 'c-turnover', text: 'Before the change, labor turnover at Ford was extremely high, at several hundred percent a year, because workers quit the repetitive line work.', when: '1913', confidence: 'probable', sourceIds: ['s-thf-5day', 's-thf-k12'], note: 'The Henry Ford\'s pages give 370 percent in one place and 380 percent in another.' },
  { id: 'c-crowds', text: 'Within days thousands of job seekers arrived from across the Midwest, rioted at the Highland Park gates, and were turned away with fire hoses in the winter cold; Ford then limited hiring to men who had lived in Detroit for six months.', when: '1914-01', confidence: 'probable', sourceIds: ['s-thf-5day'] },
  { id: 'c-socio', text: 'To qualify for the full bonus workers had to meet standards of home life, such as abstaining from alcohol, keeping a clean home, not taking in boarders and saving; the company\'s Sociological Department sent investigators to check, and the department was largely dissolved by about 1921 amid worker resentment.', when: '1914-1921', confidence: 'established', sourceIds: ['s-thf-5day', 's-wiki-ford'] },
  { id: 'c-socio-view', text: 'Whether the Sociological Department was a sincere effort to lift workers or an invasive system of control over their private lives.', when: '1914-1921', confidence: 'contested', sourceIds: ['s-thf-5day', 's-watts'], note: 'Historians still argue about Ford\'s motives for the Five Dollar Day (retaining workers, building customers, social reform, or publicity) and about how far the home inspections were paternalism. Workers\' own resentment of the intrusions is documented; the weighting of motives is interpretive.' },
  { id: 'c-dodge', text: 'In Dodge v. Ford Motor Co. (1919) the Michigan Supreme Court ordered Ford to pay a special dividend of about $19.3 million rather than spend retained profits on expansion and price cuts.', when: '1919', confidence: 'established', sourceIds: ['s-wiki-dodge'] },
  { id: 'c-rouge', text: 'Construction of the River Rouge complex in Dearborn ran from 1917 to 1928; it brought steelmaking, power and assembly into one vertically integrated site and employed up to about 100,000 people at its peak.', when: '1917-1928', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-rouge', 's-mylife'] },
  { id: 'c-peace-sail', text: 'On 4 December 1915 Ford sailed from Hoboken, New Jersey, aboard the steamship Oscar II with more than a hundred delegates and reporters on a self-financed "Peace Ship" mission to urge an end to World War I; the Hungarian pacifist Rosika Schwimmer helped organize it.', when: '1915-12-04', confidence: 'established', sourceIds: ['s-peace', 's-mylife'] },
  { id: 'c-peace-fail', text: 'Ford left the expedition after reaching Norway, citing illness, and returned to the United States; the mission did not shorten the war and was widely ridiculed, though Ford later said he did not regret trying.', when: '1915-12', confidence: 'established', sourceIds: ['s-peace', 's-mylife'] },

  // ── The Dearborn Independent ───────────────────────────────────────────
  { id: 'c-paper', text: 'Ford\'s secretary Ernest Liebold bought a small Dearborn weekly in 1918, and Ford began publishing The Dearborn Independent in January 1919; it was pushed hard through Ford dealers and reached a very large circulation in the 1920s.', when: '1918-1919', confidence: 'probable', sourceIds: ['s-wiki-dearborn'], note: undefined },
  { id: 'c-series', text: 'On 22 May 1920 The Dearborn Independent began a series titled "The International Jew: The World\'s Problem," which ran for ninety-one weeks.', when: '1920-05-22', confidence: 'established', sourceIds: ['s-thf-antisem', 's-wiki-intl'] },
  { id: 'c-protocols', text: 'The series drew on The Protocols of the Elders of Zion, a notorious forgery first published in Russia in 1903, and presented Jews as responsible for wars, financial manipulation and cultural decline.', when: '1920', confidence: 'established', sourceIds: ['s-thf-antisem', 's-wiki-dearborn'] },
  { id: 'c-volumes', text: 'The articles were reprinted as a four-volume work, The International Jew (1920–1922), distributed in large numbers and translated into many languages, including several German editions.', when: '1920-1922', confidence: 'probable', sourceIds: ['s-wiki-intl'], note: 'Reported print runs and translation counts vary by source (for example 200,000 to 500,000 copies for the first volume; 16 languages).' },
  { id: 'c-halt', text: 'Ford halted the series in January 1922 and resumed within about a year; in 1921 over a hundred prominent Americans, including former President Woodrow Wilson, had publicly condemned the campaign, and Jewish and Christian groups organized protests and boycotts.', when: '1921-1922', confidence: 'probable', sourceIds: ['s-thf-antisem', 's-wiki-dearborn'] },
  { id: 'c-roots', text: 'Historians identify several strands in Ford\'s outlook: populist distrust of bankers, wartime pacifism that blamed war on financiers, and cultural conservatism that saw Jews as agents of modern social decline.', confidence: 'probable', sourceIds: ['s-thf-antisem', 's-watts'] },
  { id: 'c-mylife-jewish', text: 'In My Life and Work (1922), published under Ford\'s name with Samuel Crowther, a chapter defends the campaign under the heading "Studies in the Jewish Question," describing it as exposure of "ideas" rather than of persons, while attributing cultural decline to a single "racial source" and insisting that the nation\'s destiny was to remain Christian.', when: '1922', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-authorship', text: 'William J. Cameron wrote the "Mr. Ford\'s Own Page" editorials and most of the series; Ernest Liebold collected material.', when: '1920-1927', confidence: 'probable', sourceIds: ['s-thf-antisem', 's-wiki-intl'] },
  { id: 'c-ford-role', text: 'How personally involved Ford was in the antisemitic articles.', when: '1920-1927', confidence: 'contested', sourceIds: ['s-wiki-intl', 's-baldwin', 's-oconnell', 's-wiki-dearborn'], note: 'Cameron testified at the Sapiro trial that Ford had nothing to do with the editorials, and Ford and his aides later said Liebold and Cameron acted without his knowledge. Baldwin and other scholars argue that Ford oversaw the paper, gave verbal direction and could not have been unaware; Baldwin describes a "paradoxical" antisemite who may not have grasped his own prejudice. The surviving record does not settle how much Ford wrote, read or approved, but his name, his money, his dealer network and his 1922 book all carried the campaign.' },
  { id: 'c-sapiro', text: 'In April 1924 the Independent attacked the San Francisco lawyer and cooperative organizer Aaron Sapiro; Sapiro sued for libel for $1 million, and the trial opened in March 1927.', when: '1924-1927', confidence: 'established', sourceIds: ['s-thf-antisem', 's-wiki-intl', 's-wiki-sapiro'] },
  { id: 'c-retraction', text: 'Ford closed The Dearborn Independent at the end of 1927 and on 30 June 1927 issued a public retraction and apology, drafted with the help of the lawyer Louis Marshall of the American Jewish Committee, which ended the Sapiro litigation.', when: '1927', confidence: 'established', sourceIds: ['s-thf-antisem', 's-wiki-intl', 's-wiki-sapiro'] },
  { id: 'c-retraction-know', text: 'Whether Ford read, understood or meant the 1927 apology he signed.', when: '1927', confidence: 'contested', sourceIds: ['s-oconnell', 's-wiki-intl'], note: 'Liebold later said Ford never read it or knew what it contained. Some historians treat the apology as a legal and commercial retreat and note that copies of The International Jew kept circulating; others accept that Ford sincerely wanted the campaign to end. Claims that the signature was forged have been made but are not established.' },
  { id: 'c-settlement', text: 'The terms of the Sapiro settlement beyond the apology and an end to Ford\'s attacks, including whether money changed hands and how much.', when: '1927', confidence: 'contested', sourceIds: ['s-thf-antisem', 's-wiki-sapiro'], note: 'The Henry Ford says the settlement included a cash payment to Sapiro; other accounts say the trial ended in a mistrial and the amount, if any, was not disclosed. The figure is not given here because no source consulted states it reliably.' },
  { id: 'c-hitler', text: 'Adolf Hitler admired Ford: Ford is the only American named in Mein Kampf, a portrait of Ford was reported to hang in Hitler\'s Munich office, and the Nazi leader Baldur von Schirach said he read The International Jew and became antisemitic.', when: '1922-1930s', confidence: 'probable', sourceIds: ['s-wiki-intl', 's-oconnell'], note: undefined },
  { id: 'c-eagle', text: 'On 30 July 1938, his seventy-fifth birthday, Ford received the Grand Cross of the German Eagle, a high Nazi honor for foreigners, at a ceremony in Dearborn; it was presented by the German consul from Cleveland, Karl Kapp, and a consular colleague.', when: '1938-07-30', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-cojs', 's-wiki-ford'] },

  // ── Depression, labor and war ──────────────────────────────────────────
  { id: 'c-fiveday', text: 'In 1926 Ford announced a five-day, forty-hour workweek for his factories, an early move that others later followed.', when: '1926', confidence: 'probable', sourceIds: ['s-wiki-ford'] },
  { id: 'c-model-a', text: 'Ford ended Model T production in May 1927 and introduced the Model A in December 1927; the River Rouge plant then became his main production site.', when: '1927', confidence: 'established', sourceIds: ['s-wiki-modelt', 's-wiki-rouge'] },
  { id: 'c-hunger', text: 'On 7 March 1932 several thousand unemployed workers marched toward the Rouge to present demands; Dearborn police and Ford security guards fired on the marchers, killing four that day, and a fifth died of wounds months later.', when: '1932-03-07', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-wiki-hunger', 's-wiki-rouge'], note: undefined },
  { id: 'c-bennett', text: 'Harry Bennett headed Ford\'s Service Department, which ran a spy network inside the plants, watched union meetings and hired rough men to intimidate organizers.', when: '1930s', confidence: 'established', sourceIds: ['s-reuther'] },
  { id: 'c-overpass', text: 'On 26 May 1937, at the Rouge overpass, Service Department men beat United Automobile Workers organizers including Walter Reuther and Richard Frankensteen as they prepared to hand out leaflets; the photographer James Kilpatrick saved his pictures, and their publication hurt Ford\'s reputation and helped the union.', when: '1937-05-26', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-reuther', 's-wiki-overpass'] },
  { id: 'c-1941', text: 'After a walkout at the Rouge began on 1 April 1941, Ford, the last of the major Detroit automakers to hold out, signed a contract with the UAW-CIO on 20 June 1941.', when: '1941-06-20', confidence: 'established', sourceIds: ['s-history-1941', 's-wiki-overpass'] },
  { id: 'c-clara', text: 'Ford\'s wife, Clara, is reported to have urged him to sign, fearing more bloodshed and threatening to leave him.', when: '1941', confidence: 'tradition', sourceIds: ['s-history-1941'], note: 'The story comes from later retellings of family and company memory and is widely repeated; it cannot be checked against a contemporary record.' },
  { id: 'c-fordlandia', text: 'In 1928 Ford began Fordlândia, a rubber plantation town in the Brazilian Amazon on the Tapajós River, to secure rubber for his cars; he imposed American work rules and diet, the trees were struck by blight and pests, and the project was sold back to Brazil in 1945 at a heavy loss. Ford never visited it.', when: '1928-1945', where: 'Pará, Brazil', confidence: 'established', sourceIds: ['s-wiki-fordlandia', 's-grandin'] },
  { id: 'c-fordlandia-labor', text: 'Resentment of the strict rules, the food and the heat of midday work led to a workers\' uprising at Fordlândia in 1930.', when: '1930', confidence: 'probable', sourceIds: ['s-wiki-fordlandia', 's-grandin'] },
  { id: 'c-willow', text: 'At Willow Run, Michigan, Ford built B-24 Liberator bombers from 1942; the plant produced close to half of all B-24s, and by 1944 a bomber was leaving the line about every hour.', when: '1942-1945', where: 'Willow Run, Michigan', confidence: 'probable', sourceIds: ['s-wiki-willow', 's-thf-k12'], note: 'Counts vary: about 6,800 to 7,000 complete aircraft, or about 8,600 when knock-down kits are included, out of roughly 18,000 B-24s overall. Cycle times quoted range from about 59 to 63 minutes.' },
  { id: 'c-willow-labor', text: 'Willow Run struggled with worker shortages, housing and absenteeism; Ford initially resisted hiring women but wartime need brought many women into the plant.', when: '1942-1944', confidence: 'probable', sourceIds: ['s-wiki-willow'] },

  // ── Final years and legacy ─────────────────────────────────────────────
  { id: 'c-foundation', text: 'The Ford Foundation was established on 15 January 1936 by Edsel Ford and Henry Ford; after their deaths, Ford Motor Company stock bequests made it one of the largest philanthropies in the world.', when: '1936', confidence: 'probable', sourceIds: ['s-wiki-foundation'] },
  { id: 'c-edsel', text: 'Edsel Ford, Henry\'s only child, served as president of Ford Motor Company from 1919, often clashed with his father over cars and policy, and died of stomach cancer on 26 May 1943 at age 49.', when: '1943-05-26', confidence: 'established', sourceIds: ['s-wiki-edsel', 's-wiki-ford'] },
  { id: 'c-edsel-stress', text: 'Whether the conflict with his father and with Harry Bennett contributed to Edsel Ford\'s decline and early death.', when: '1943', confidence: 'contested', sourceIds: ['s-wiki-edsel', 's-watts'], note: 'Family members and some biographers say the strain hastened Edsel\'s illness. Stomach cancer is the documented cause of death; the link to the conflicts is an interpretation that cannot be shown from medical evidence.' },
  { id: 'c-1945', text: 'In 1945, after pressure from his wife Clara and Edsel\'s widow Eleanor, Ford gave up the presidency, and his grandson Henry Ford II took over the company.', when: '1945', confidence: 'probable', sourceIds: ['s-wiki-ford', 's-wiki-edsel'] },
  { id: 'c-death', text: 'Henry Ford died on 7 April 1947, aged 83, at his estate, Fair Lane, in Dearborn, of a cerebral hemorrhage, on a night when flooding on the Rouge River had cut power to the house.', when: '1947-04-07', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-wiki-ford', 's-flood'], note: undefined },
  { id: 'c-hist', text: 'Historians disagree on how to weigh Ford\'s achievements against his antisemitism and his labor record.', confidence: 'contested', sourceIds: ['s-watts', 's-baldwin'], note: 'Watts\'s The People\'s Tycoon is a broad biography that treats Ford\'s bigotry in a separate chapter and describes his ideas as a mishmash of half-digested concepts rather than a system; Baldwin\'s Henry Ford and the Jews centers the campaign and its legacy. Reviewers disagree about which framing best explains the man; this dossier presents both records at full strength.' },

  // ── Added in the automotive-and-war revision (Detroit, the cars, the war, then beliefs) ──────────
  // Detroit and the first cars
  { id: 'c-first-car-date', text: `Which year Ford built his first motor car: the Quadricycle test-driven on 4 June 1896, or an earlier car he dated himself to 1892-1893.`, when: '1892-1896', confidence: 'contested', sourceIds: ['s-mylife', 's-thf-edison'], note: `In My Life and Work (1922) Ford wrote that he completed his first motor car in 1892 and that it ran to his satisfaction in the spring of the following year, describing a buggy-like car with two cylinders over the rear axle. The Henry Ford and standard histories date the Quadricycle, the first Ford car that survives in the record, to 1896. The two accounts may describe different machines or a lapse of memory; this dossier gives the dated 1896 test drive and flags the earlier claim.` },
  { id: 'c-ford-early-account', text: `Ford wrote later that investors formed the Detroit Automobile Company to exploit his car, that it sold very few cars and was a money-making concern rather than a vehicle for his ideas, and that he resigned in 1902.`, when: '1899-1902', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-ford'], note: `This is Ford's own retrospective account. Wikipedia dates the dissolution of the Detroit Automobile Company to January 1901 and the Henry Ford Company to November 1901, so his memory of the sequence is compressed.` },
  { id: 'c-piquette-plant', text: `Ford Motor Company's Piquette Avenue Plant in Detroit was a three-story brick factory about 402 feet long and 56 feet wide, designed by Field, Hinchman and Smith, where the company built the Models B, C, F, K, N, R, S and T; Ford moved in during October 1904 and had left by October 1910.`, when: '1904-1910', where: 'Detroit, Michigan', confidence: 'contested', sourceIds: ['s-wiki-piquette', 's-piquette-museum', 's-mylife'], note: `Wikipedia dates the building to 1904 and Ford's move to October 1904. In My Life and Work Ford wrote that "in 1906" the firm took working capital to build a three-story plant at Piquette and Beaubien streets. The dates disagree (Ford may be remembering an expansion or simply misdating). The Henry Ford's c.1906 view of the building shows the Ford Motor Co. sign; the plant's own museum should be asked for the construction record.` },
  { id: 'c-piquette-modelt', text: `The Model T was designed from January 1907 in a room in the northeast corner of the Piquette plant's third floor by a small group that included Henry Ford, the draftsman Joseph Galamb, the engineer C. Harold Wills and the machinist C. J. Smith; the first production Model T was completed there on 27 September 1908, and the first 14,000 or so American-built cars were assembled at Piquette.`, when: '1907-1908', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-piquette', 's-piquette-museum'], note: `The room, the team and the 27 September 1908 date come from the Wikipedia article, which itself rests on the museum's research; the museum site consulted confirms only that Piquette was the Model T's birthplace. Design credit for the T is shared (see the ledger note on the moving line) and Eugene Farkas is also named in the literature.` },
  { id: 'c-piquette-status', text: `The Piquette Avenue Plant was listed on the National Register of Historic Places in 2002, named a Michigan State Historic Site in 2003 and designated a National Historic Landmark in 2006; it has operated as a museum, the Model T Automotive Heritage Complex, since 2001.`, when: '2001-2006', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-piquette', 's-piquette-museum'] },

  // The car for the great multitude
  { id: 'c-car-luxury', text: `Ford wrote that when he planned the Model T a motor car was still regarded as a luxury, that manufacturers had marketed it as a "pleasure car," and that his announcement of a low-priced single model met the response that "If Ford does that he will be out of business in six months."`, when: '1908-1909', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-modelt-engineering', text: `The Model T had a four-cylinder engine of about 177 cubic inches producing 20 horsepower, used vanadium steel for strength, and could run on gasoline, kerosene or ethanol; Joseph Galamb is credited as the main engineer, with Eugene Farkas and C. Harold Wills, under Ford's direction.`, when: '1908', confidence: 'probable', sourceIds: ['s-wiki-modelt', 's-wiki-piquette'], note: undefined },
  { id: 'c-modelt-sales-1909', text: `Ford wrote that the 1908-1909 sales of more than ten thousand cars convinced him the company needed a new factory, and that he bought sixty acres at Highland Park, which was then considered far out in the country from Detroit.`, when: '1909', confidence: 'probable', sourceIds: ['s-mylife'], note: `Self-reported in My Life and Work (1922); the sales figure and the sixty acres are Ford's own account.` },
  { id: 'c-highland-site', text: `Albert Kahn's firm designed the Highland Park plant; it opened in 1910, covered about 102 acres, became a National Historic Landmark in 1978, and kept making tractors and other products after car assembly moved to the Rouge in the late 1920s.`, when: '1908-1928', where: 'Highland Park, Michigan', confidence: 'probable', sourceIds: ['s-wiki-highland', 's-mylife'], note: `Ford's book says he bought sixty acres at Highland Park; a modern summary gives about 102 acres for the plant. The difference is probably later expansion, but that is an inference.` },
  { id: 'c-village-industries', text: `From 1920, beginning with a valve plant at Northville, Ford opened small Village Industries factories in rural southeast Michigan, often on rivers, to make tools and vehicle parts while letting workers, ideally farmers, divide their time between factory and farm; one mill at Tecumseh processed soybeans for paints and plastics, and in the Second World War these plants turned to defense work.`, when: '1920-1944', where: 'southeast Michigan', confidence: 'probable', sourceIds: ['s-thf-village'], note: `Ford's own motives and the later claim that the plants embodied a moral ideal of rural life are interpretive; The Henry Ford's set describes purpose and practice but not the beliefs behind them, and the 20-plant total reported elsewhere is not used here.` },
  { id: 'c-5day-effects', text: `The Henry Ford presents the Five Dollar Day as a measure that kept workers on the line, helped create customers for the cars, and pushed wages up across the industry.`, when: '1914', confidence: 'probable', sourceIds: ['s-thf-5day'], note: `Interpretive: the archive article states these effects; economists and historians weigh them differently (see the contested ledger entry on motives).` },

  // The Motor City engine
  { id: 'c-detroit-boom', text: `By 1920 Detroit's automakers produced roughly half of the world's automobiles, which earned the city the nickname Motor City.`, when: '1920', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-detroit'], note: undefined },
  { id: 'c-english-school', text: `In 1914 Ford opened the Ford English School at Highland Park to teach immigrant workers English, civics and citizenship; it grew from 20 students and one instructor to more than 2,200 students and nearly 150 instructors by 1916, and graduations staged a "Melting Pot" ceremony in which students in native dress stepped into a pot and emerged in American suits.`, when: '1914-1916', where: 'Highland Park, Michigan', confidence: 'established', sourceIds: ['s-thf-socio'], note: undefined },
  { id: 'c-migration', text: `Detroit's Black population grew from 5,741 in 1910 to 40,838 in 1920, most of the growth between 1915 and 1920, as the Great Migration drew Southern Black families north.`, when: '1910-1920', where: 'Detroit, Michigan', confidence: 'established', sourceIds: ['s-thf-aaworkers'], note: undefined },
  { id: 'c-black-workforce', text: `By the end of the First World War more than 8,000 Black workers were employed in Detroit's auto industry, 1,675 of them at Ford; through the 1920s and 1930s Ford was the largest employer of Black workers in the city, paid Black and white workers the same for the same jobs according to The Henry Ford, and hired through Henry Ford's personal ties with Black ministers, though many of the jobs were in the foundries and blast furnaces and some Black workers rose to skilled and foreman positions.`, when: '1918-1930s', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-thf-aaworkers'], note: undefined },
  { id: 'c-black-weigh', text: `How to weigh Ford's employment of Black workers: as a rare opening in a segregated labor market, or as paternalism that depended on loyalty to Henry Ford and kept Black workers in the hardest jobs.`, when: '1920s-1941', confidence: 'contested', sourceIds: ['s-thf-aaworkers'], note: `The Henry Ford's article stresses the opportunity, equal pay and the role of Black churches in placing workers, while also noting how much of the work was in dangerous foundries. The wider scholarship on Black Detroit and the UAW is not consulted in this dossier; a historian should add it before this question is treated as settled.` },
  { id: 'c-fordson', text: `Ford's Fordson tractor went into production in 1917, a year earlier than planned because of Britain's wartime food emergency; Ford wrote that five thousand were shipped across the Atlantic in 1917-18 and that Fordson's price, first $750, was cut to $395 in 1922.`, when: '1917-1922', where: 'Dearborn, Michigan', confidence: 'established', sourceIds: ['s-mylife', 's-wiki-fordson'], note: undefined },
  { id: 'c-lincoln', text: `Ford bought the Lincoln Motor Company, founded by Henry Leland, on 4 February 1922 for $8 million; Edsel Ford had urged the purchase and managed the brand afterward, and Leland and his son resigned in June 1922.`, when: '1922', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-lincoln'], note: undefined },
  { id: 'c-trade-school', text: `The Henry Ford Trade School began in 1916 with six boys and one instructor at Highland Park; boys aged 12 to 15, with priority for poor boys and those from fatherless homes, split their days between classroom work and shop training and were paid while they learned; it had more than 2,000 students by 1931 and closed in July 1952.`, when: '1916-1952', where: 'Highland Park and Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-thf-tradeschool'], note: undefined },
  { id: 'c-hospital', text: `Henry Ford Hospital in Detroit opened on 1 October 1915 after Ford took over a stalled hospital project in 1914 and paid off its original donors; it became the core of today's Henry Ford Health.`, when: '1914-1915', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-hospital'], note: undefined },
  { id: 'c-greenfield', text: `Greenfield Village and the Henry Ford Museum, then called the Edison Institute, were dedicated on 21 October 1929 during Light's Golden Jubilee, with President Herbert Hoover presiding, and opened to the public on 22 June 1933.`, when: '1929-1933', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-greenfield', 's-thf-edison'], note: undefined },
  { id: 'c-ww1-ford', text: `Ford wrote that before the United States entered the war the company refused war orders from the foreign belligerents, but that once the country was in the war every facility of the Ford industries was put at the Government's disposal, and from April 1917 to November 1918 the factory worked practically exclusively for the Government, making trucks, ambulances, Liberty motors, aero cylinders, caissons, steel helmets and Eagle boats.`, when: '1917-1918', confidence: 'probable', sourceIds: ['s-mylife', 's-thf-ambulance'], note: `The list and the dates are Ford's own account in My Life and Work (1922); The Henry Ford independently confirms ambulances, helmets, tanks and caissons among Ford's wartime products.` },
  { id: 'c-eagle-boats', text: `Ford built the Eagle boats, 204-foot steel anti-submarine patrol craft designed by the Navy, in a special plant at the River Rouge: the Navy awarded the contract on 15 January 1918, the first boat was launched on 11 July 1918, the plant was raised in about four months, but only seven boats were commissioned in 1918 and none saw combat in the war.`, when: '1918-1919', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-eagle', 's-thf-ambulance'], note: `Order sizes differ by account: the Navy contracted for 100 boats in January 1918, raised the order to 112 and cut it to 60 completed boats after the Armistice (Wikipedia); Ford's book says the first launch was in July 1918. Wikipedia's article says Ford contributed little to the fundamental design beyond pressing for simplified, flat-plated hulls and turbines.` },
  { id: 'c-ambulances', text: `Ford donated $500,000 to the Red Cross, which bought nearly 1,000 vehicles including 107 ambulances, and Ford staff worked with the Surgeon General's Office and frontline drivers on a Model T ambulance; another 5,745 ambulances were built for the Allied armies.`, when: '1917-1918', confidence: 'established', sourceIds: ['s-thf-ambulance'], note: undefined },
  { id: 'c-liberty', text: `Ford made Liberty aircraft engines and aero cylinders in the First World War; Wikipedia credits Ford with a faster method of cutting and pressing steel cylinders that raised output from 151 a day to more than 2,000, while Henry Leland's Lincoln Motor Company delivered about 6,500 complete Liberty engines.`, when: '1917-1919', confidence: 'probable', sourceIds: ['s-mylife', 's-wiki-liberty'], note: `Counts of complete Liberty engines built by Ford are not stated here because the sources consulted disagree or do not give a verified figure.` },
  { id: 'c-trimotor', text: `Ford acquired William Stout's Stout Metal Airplane company in 1925; the all-metal Ford Trimotor, nicknamed the Tin Goose, first flew on 11 June 1926, and 199 were built before production ended in 1933.`, when: '1925-1933', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-trimotor', 's-wiki-ford'], note: undefined },

  // V-8, design and the Depression
  { id: 'c-v8', text: `Ford's flathead V-8, introduced in 1932, was the first affordable V-8: its eight cylinders and crankcase were cast in a single block, and the engine stayed in American production for 21 years, to 1953.`, when: '1932', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-flathead', 's-wiki-ford'], note: undefined },
  { id: 'c-edsel-design', text: `Edsel Ford, who urged the 1922 Lincoln purchase and managed the brand, oversaw the Lincoln-Zephyr (1936) and the Lincoln Continental (1939); as president he often clashed with his father over cars and policy.`, when: '1922-1939', confidence: 'probable', sourceIds: ['s-wiki-lincoln', 's-wiki-edsel'], note: undefined },
  { id: 'c-mercury', text: `Edsel Ford created the Mercury marque, unveiled in November 1938 as the 1939 Mercury Eight between the Ford V-8 and the Lincoln-Zephyr, with styling overseen by E. T. Gregorie; more than 65,000 were sold in its first year.`, when: '1938-1939', confidence: 'probable', sourceIds: ['s-wiki-mercury'], note: undefined },

  // Arsenal of democracy
  { id: 'c-willow-scale', text: `The Willow Run plant near Ypsilanti, designed by Albert Kahn and built from 1940 to 1942, held about 3.5 million square feet under one roof; the first Ford-built B-24 Liberator rolled out in September 1942, output peaked at 428 aircraft in April 1944, and employment peaked at about 42,000.`, when: '1940-1944', where: 'Willow Run, Michigan', confidence: 'probable', sourceIds: ['s-wiki-willow'], note: `Wikipedia gives 6,972 of 18,482 B-24s as complete Ford-built aircraft; other sources count about 8,685 including knock-down kits. Peak employment is reported as 42,331 or 42,500.` },
  { id: 'c-willow-housing', text: `Willow Run's workers struggled to find homes near a plant almost an hour from Detroit: federal and Ford-related projects added Willow Lodge dormitories in February 1943, about 2,500 family homes at Willow Village by December 1943 and Parkridge Homes, 80 units for Black war workers.`, when: '1943', where: 'Ypsilanti, Michigan', confidence: 'probable', sourceIds: ['s-wiki-willow'], note: `Housing figures are from a tertiary summary; the builders and agencies behind each project are not given here.` },
  { id: 'c-willow-turnover', text: `Turnover and absenteeism plagued Willow Run early on (one month the plant hired 2,900 workers and lost 3,100), and a 1943 Congressional committee criticised Ford for a line that too closely resembled automobile assembly for building bombers.`, when: '1942-1943', confidence: 'probable', sourceIds: ['s-wiki-willow'], note: undefined },
  { id: 'c-gpw', text: `Ford built about 278,000 GPW jeeps during the war to Willys's design after the Army standardised the vehicle; the jeep was assembled in several Ford plants, not only the Rouge.`, when: '1941-1945', confidence: 'probable', sourceIds: ['s-wiki-willys'], note: `Totals differ by source and by whether amphibious GPA variants are counted: Wikipedia's production table gives 277,896 GPWs, and some enthusiast sources about 282,000.` },
  { id: 'c-gaa', text: `Ford's GAA engine, an 1,100-cubic-inch aluminium V-8 rated at about 500 horsepower, powered the M4A3 Sherman tank; it grew from Ford's plan to build an aircraft engine and was produced from the early 1940s.`, when: '1940-1945', confidence: 'probable', sourceIds: ['s-wiki-gaa'], note: undefined },
  { id: 'c-gliders', text: `Ford built 4,190 Waco CG-4A troop gliders at its Iron Mountain plant in Kingsford, Michigan, more than any other company, between 1942 and 1945.`, when: '1942-1945', where: 'Kingsford, Michigan', confidence: 'probable', sourceIds: ['s-wiki-cg4'], note: undefined },

  // Beliefs and morals
  { id: 'c-modelt-god', text: `In the same announcement of the single-model plan, Ford spoke of the family's "hours of pleasure in God's great open spaces," putting a religious phrase at the center of his sales pitch.`, when: '1909', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-temperance', text: `Ford campaigned for sobriety and against tobacco: in 1914 he published the brochure The Case Against the Little White Slaver on the dangers of cigarettes, influenced by Thomas Edison's refusal to employ smokers; his Five Dollar Day bonus required workers to abstain from alcohol; and in My Life and Work he called making liquor from corn "not a very good use for good corn."`, when: '1914-1922', confidence: 'established', sourceIds: ['s-thf-lsw', 's-thf-5day', 's-mylife'], note: undefined },
  { id: 'c-marquis', text: `Ford appointed Samuel S. Marquis, an Episcopal clergyman, to head the Sociological Department, whose investigators visited homes and checked cleanliness, savings, school attendance and divorce filings and rated housing as Good, Fair or Poor.`, when: '1914-1921', confidence: 'established', sourceIds: ['s-thf-socio'], note: undefined },
  { id: 'c-pacifism-not', text: `Ford wrote in 1922 that his opposition to war was "not based upon pacifist or non-resistant principles," that "wars do not end wars," that a man who opposes war should oppose going to war only until the moment of declaration, and that once the United States was in the war every citizen's duty was to see it through.`, when: '1915-1922', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },
  { id: 'c-reincarnation', text: `In an interview in the San Francisco Examiner on 26 August 1928, Ford said, "I adopted the theory of Reincarnation when I was twenty six," and that the idea put his mind at ease because the experience gathered in one life could be used in the next.`, when: '1928-08-26', confidence: 'established', sourceIds: ['s-thf-reinc'], note: undefined },
  { id: 'c-reincarnation-origin', text: `When and how Ford came to believe in reincarnation.`, when: '1889-1928', confidence: 'contested', sourceIds: ['s-thf-reinc'], note: `The Henry Ford says Ford credited Orlando J. Smith's book A Short View of Great Questions, first published in 1899. Ford was born in 1863, so age twenty-six falls in 1889-1890, before that book appeared. Either his memory of his own age is loose or another source first led him to the idea; the 1928 interview is the best-documented statement of the belief.` },
  { id: 'c-independent-frame', text: `My Life and Work (1922) framed the Dearborn Independent campaign in moral and religious terms: it spoke of "ideas, false ideas, which are sapping the moral stamina of the people," and insisted that the nation's destiny was to remain Christian, while disclaiming "prejudice or hatred against persons."`, when: '1922', confidence: 'established', sourceIds: ['s-mylife'], note: undefined },

  // Legacy
  { id: 'c-modelt-legacy', text: `The Model T remained the best-selling car in history until the Volkswagen Beetle passed its total in 1972.`, when: '1972', confidence: 'probable', sourceIds: ['s-wiki-modelt'], note: undefined },
  { id: 'c-detroit-decline', text: `Detroit's population peaked at about 1.85 million in 1950 and has since fallen by roughly 65 percent, through industrial decentralisation and suburbanisation, to the city's Chapter 9 bankruptcy filing in July 2013; recent figures show its first population growth since the late 1950s in 2024.`, when: '1950-2024', where: 'Detroit, Michigan', confidence: 'probable', sourceIds: ['s-wiki-detroit'], note: undefined },
  { id: 'c-museum-today', text: `The Henry Ford, the museum and Greenfield Village that Ford founded, is today the largest indoor-outdoor history museum complex in the country, with nearly a hundred relocated historic buildings in the village and the Wright brothers' bicycle shop, Edison's Menlo Park laboratory replica and the Rosa Parks bus among its collections.`, when: '1929-today', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-greenfield', 's-thf-edison'], note: undefined },
  { id: 'c-rouge-today', text: `The Rouge complex was declared a National Historic Landmark in 1978, still builds vehicles including the F-150 Lightning after a $700 million investment announced in 2020, and drew visitors such as the muralist Diego Rivera in 1932, who studied it for his Detroit Industry murals.`, when: '1932-2020', where: 'Dearborn, Michigan', confidence: 'probable', sourceIds: ['s-wiki-rouge'], note: undefined },
  // What the printed pages show (read from the images)
  { id: 'c-page-reprint', text: `The title page of The International Jew, dated November 1920, states that the book is a reprint of a series of articles that appeared in The Dearborn Independent from 22 May to 2 October 1920.`, when: '1920-11', confidence: 'established', sourceIds: ['s-img-intl'], note: undefined },
  { id: 'c-page-1921', text: `The front page of The Dearborn Independent, subtitled "The Ford International Weekly," for 6 August 1921 lists an article headlined "Jewish Jazz—Moron Music—Becomes Our National Music" among features on leprosy, John Muir's home, the Supreme Court and sweet potatoes, so that the paper's hostility appeared inside an ordinary general-interest weekly.`, when: '1921-08-06', confidence: 'established', sourceIds: ['s-img-1921'], note: undefined },
  { id: 'c-page-1927', text: `The cover of The Dearborn Independent for 11 June 1927, nineteen days before Ford's retraction of 30 June, carries an illustration of boys at a foundry captioned "Teaching boys to do as well as to know," a feature on trade training.`, when: '1927-06-11', confidence: 'established', sourceIds: ['s-img-1927'], note: undefined },
];

